/* ============================================================
   js/vendor/tinos-vietnamese-jspdf.js
   Font Unicode "Tinos" — bản THAY THẾ MIỄN PHÍ, tương thích số đo (metric-
   compatible) với Times New Roman của Google Fonts (SIL Open Font License
   1.1) — dùng cho "Phiếu công tác" (mẫu On_Tap_MOS/Phieu cong tac.doc)
   để giữ đúng KIỂU CHữ SERIF của file Word gốc.

   KHÔNG dùng trực tiếp font "Times New Roman" của Microsoft: đó là font
   độc quyền đi kèm hệ điều hành/Office, không được phép đóng gói phân
   phối lại trong mã nguồn ứng dụng (khác với việc 1 file .docx/.pdf tự
   nhúng font khi người dùng lưu trên máy có sẵn font). Tinos được thiết
   kế RIÊNG để thay thế Times New Roman — cùng độ rộng ký tự/số dòng mỗi
   trang khi in, nhìn gần như giống hệt, nhưng cấp phép mở nên nhúng thoải
   mái vào vendor bundle như NotoSans đang dùng cho các bản in khác.

   Nguồn: Google Fonts "Tinos" (SIL Open Font License 1.1), subset =
   Latin + Latin-1 Supplement + Latin Extended-A/B + Latin Extended
   Additional (đủ nguyên âm có dấu tiếng Việt) bằng fontTools.subset,
   ~100-115KB/file thay vì ~500KB bản đầy đủ.

   Đăng ký theo đúng cơ chế chính thức của jsPDF (jsPDF.API.events) — mỗi
   jsPDF() instance mới tạo ra sẽ TỰ ĐỘNG có sẵn font "Tinos" (4 kiểu:
   normal/bold/italic/bolditalic).
   Nạp SAU js/vendor/jspdf.umd.min.js, TRƯỚC code gọi doc.setFont('Tinos', ...).
   ============================================================ */
(function () {
  'use strict';
  if (typeof window.jspdf === 'undefined' || !window.jspdf.jsPDF) return;

  var REGULAR_B64 = '';
  var BOLD_B64 = '';
  var ITALIC_B64 = '';
  var BOLDITALIC_B64 = '';

  window.jspdf.jsPDF.API.events.push(['addFonts', function () {
    this.addFileToVFS('Tinos-Regular.ttf', REGULAR_B64);
    this.addFont('Tinos-Regular.ttf', 'Tinos', 'normal');
    this.addFileToVFS('Tinos-Bold.ttf', BOLD_B64);
    this.addFont('Tinos-Bold.ttf', 'Tinos', 'bold');
    this.addFileToVFS('Tinos-Italic.ttf', ITALIC_B64);
    this.addFont('Tinos-Italic.ttf', 'Tinos', 'italic');
    this.addFileToVFS('Tinos-BoldItalic.ttf', BOLDITALIC_B64);
    this.addFont('Tinos-BoldItalic.ttf', 'Tinos', 'bolditalic');
  }]);
})();
